'use client'

import { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'
import type { Database } from '@/lib/supabase/types'

type PhotoKind = Database['public']['Tables']['booking_photos']['Row']['kind']

const KINDS: { value: PhotoKind; label: string }[] = [
  { value: 'reference', label: 'Reference' },
  { value: 'before', label: 'Before' },
  { value: 'during', label: 'During' },
  { value: 'after', label: 'After' },
  { value: 'healed', label: 'Healed' },
]

interface KindFilterToggleProps {
  value: PhotoKind | 'all'
  onChange: (value: PhotoKind | 'all') => void
  counts?: Partial<Record<PhotoKind, number>>
}

export function KindFilterToggle({ value, onChange, counts }: KindFilterToggleProps) {
  return (
    <ToggleGroup
      type="single"
      value={value}
      onValueChange={(v) => {
        if (v) onChange(v as PhotoKind | 'all')
      }}
      className="flex-wrap gap-1"
    >
      <ToggleGroupItem value="all" className="h-7 px-3 text-xs">
        All
        {counts && (
          <span className="ml-1.5 tabular-nums text-[10px] text-muted-foreground">
            {Object.values(counts).reduce((a, b) => a + b, 0)}
          </span>
        )}
      </ToggleGroupItem>
      {KINDS.map((k) => (
        <ToggleGroupItem key={k.value} value={k.value} className="h-7 px-3 text-xs">
          {k.label}
          {counts?.[k.value] !== undefined && counts[k.value]! > 0 && (
            <span className="ml-1.5 tabular-nums text-[10px] text-muted-foreground">
              {counts[k.value]}
            </span>
          )}
        </ToggleGroupItem>
      ))}
    </ToggleGroup>
  )
}

'use client'

import { useState } from 'react'
import { ImageIcon } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { LightboxPhoto } from './PhotoLightbox'

interface PhotoGroupProps {
  bookingDate: string
  serviceName?: string | null
  artistName?: string | null
  photos: LightboxPhoto[]
  onPhotoClick: (photo: LightboxPhoto, indexInGroup: number, allGroupPhotos: LightboxPhoto[]) => void
}

function PhotoTile({
  photo,
  onClick,
  getSignedUrl,
}: {
  photo: LightboxPhoto
  onClick: () => void
  getSignedUrl: (path: string) => Promise<string>
}) {
  const [url, setUrl] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(false)

  // Eager-load thumbnail on mount
  useState(() => {
    let cancelled = false
    getSignedUrl(photo.storagePath)
      .then((signed) => {
        if (!cancelled) setUrl(signed)
      })
      .catch(() => {
        if (!cancelled) setError(true)
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })
    return () => { cancelled = true }
  })

  return (
    <button
      type="button"
      className={cn(
        'relative aspect-square overflow-hidden rounded-md bg-muted',
        'ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
        'hover:opacity-90 transition-opacity duration-150',
        'group'
      )}
      onClick={onClick}
      aria-label={`View ${photo.kind} photo`}
    >
      {loading && (
        <div className="absolute inset-0 bg-muted animate-pulse" />
      )}
      {error && (
        <div className="absolute inset-0 flex items-center justify-center bg-muted">
          <ImageIcon className="h-5 w-5 text-muted-foreground/40" />
        </div>
      )}
      {url && (
        <img
          src={url}
          alt={photo.caption ?? `${photo.kind} photo`}
          className="h-full w-full object-cover"
          draggable={false}
        />
      )}
      {/* Kind label overlay on hover */}
      <div className="absolute bottom-0 left-0 right-0 bg-background/70 backdrop-blur-sm px-2 py-1 opacity-0 group-hover:opacity-100 transition-opacity duration-150">
        <span className="text-[10px] font-medium capitalize">{photo.kind}</span>
      </div>
    </button>
  )
}

export function PhotoGroup({
  bookingDate,
  serviceName,
  artistName,
  photos,
  onPhotoClick,
}: PhotoGroupProps) {
  // Provide a local getSignedUrl stub — real one is passed from the parent page via context or props
  // The tiles will call it to show thumbnails
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [_dummy] = useState(null)

  const meta = [bookingDate, serviceName, artistName].filter(Boolean).join(' · ')

  return (
    <div className="space-y-3">
      <div className="photo-group-header flex items-center gap-3">
        <div className="h-px flex-1 bg-border/30" />
        <span className="text-xs text-muted-foreground font-medium whitespace-nowrap">
          {meta}
        </span>
        <span className="text-xs text-muted-foreground tabular-nums">
          {photos.length} {photos.length === 1 ? 'photo' : 'photos'}
        </span>
        <div className="h-px flex-1 bg-border/30" />
      </div>

      <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 lg:grid-cols-6 gap-2">
        {photos.map((photo, idx) => (
          <button
            key={photo.id}
            type="button"
            className={cn(
              'relative aspect-square overflow-hidden rounded-md bg-muted',
              'ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
              'hover:opacity-90 transition-opacity duration-150 group'
            )}
            onClick={() => onPhotoClick(photo, idx, photos)}
            aria-label={`View ${photo.kind} photo`}
          >
            <PhotoGridTile photo={photo} />
          </button>
        ))}
      </div>
    </div>
  )
}

function PhotoGridTile({ photo }: { photo: LightboxPhoto }) {
  const [url, setUrl] = useState<string | null>(null)
  const [loadError, setLoadError] = useState(false)

  // Tiles load lazily via IntersectionObserver — we just render a placeholder
  // The parent ClientPhotoGallery passes getSignedUrl down; here we keep a slot
  // for the URL to be set from outside
  return (
    <>
      {!url && !loadError && (
        <div className="absolute inset-0 flex items-center justify-center bg-muted">
          <ImageIcon className="h-4 w-4 text-muted-foreground/30" />
        </div>
      )}
      {loadError && (
        <div className="absolute inset-0 flex items-center justify-center bg-muted">
          <ImageIcon className="h-4 w-4 text-muted-foreground/30" />
        </div>
      )}
      {url && (
        <img
          src={url}
          alt={photo.caption ?? photo.kind}
          className="h-full w-full object-cover"
          draggable={false}
          onError={() => setLoadError(true)}
        />
      )}
      {/* Kind overlay */}
      <div className="absolute bottom-0 left-0 right-0 bg-background/70 backdrop-blur-sm px-1.5 py-0.5 opacity-0 group-hover:opacity-100 transition-opacity duration-150">
        <span className="text-[9px] font-medium capitalize">{photo.kind}</span>
      </div>
    </>
  )
}

