}

'use client'

import { useState, useMemo, useCallback } from 'react'
import { ImageIcon } from 'lucide-react'
import { PhotoGroup } from './PhotoGroup'
import { PhotoLightbox, type LightboxPhoto } from './PhotoLightbox'
import { KindFilterToggle } from './KindFilterToggle'
import type { Database } from '@/lib/supabase/types'

type PhotoKind = Database['public']['Tables']['booking_photos']['Row']['kind']

interface BookingInfo {
  id: string
  scheduledAt: string
  serviceName?: string | null
  artistName?: string | null
}

interface RawPhoto {
  id: string
  storagePath: string
  kind: PhotoKind
  caption: string | null
  bookingId: string
}

interface ClientPhotoGalleryProps {
  photos: RawPhoto[]
  bookings: BookingInfo[]
  getSignedUrl: (storagePath: string) => Promise<string>
}

function formatBookingDate(iso: string): string {
  return new Date(iso).toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  })
}

export function ClientPhotoGallery({ photos, bookings, getSignedUrl }: ClientPhotoGalleryProps) {
  const [kindFilter, setKindFilter] = useState<PhotoKind | 'all'>('all')
  const [lightboxOpen, setLightboxOpen] = useState(false)
  const [lightboxIndex, setLightboxIndex] = useState(0)

  // Build booking lookup
  const bookingMap = useMemo(() => {
    const m = new Map<string, BookingInfo>()
    for (const b of bookings) m.set(b.id, b)
    return m
  }, [bookings])

  // Group photos by booking, sorted reverse-chronological
  const grouped = useMemo(() => {
    const map = new Map<string, RawPhoto[]>()
    for (const p of photos) {
      const arr = map.get(p.bookingId) ?? []
      arr.push(p)
      map.set(p.bookingId, arr)
    }
    // Sort groups by booking date desc
    const entries = [...map.entries()].sort((a, b) => {
      const dateA = bookingMap.get(a[0])?.scheduledAt ?? ''
      const dateB = bookingMap.get(b[0])?.scheduledAt ?? ''
      return dateB.localeCompare(dateA)
    })
    return entries
  }, [photos, bookingMap])

  // Filtered photos per group
  const filteredGrouped = useMemo(() => {
    return grouped.map(([bookingId, groupPhotos]) => ({
      bookingId,
      photos: kindFilter === 'all'
        ? groupPhotos
        : groupPhotos.filter((p) => p.kind === kindFilter),
    })).filter((g) => g.photos.length > 0)
  }, [grouped, kindFilter])

  // Flat list of LightboxPhotos for the lightbox (filtered)
  const flatLightboxPhotos = useMemo<LightboxPhoto[]>(() => {
    return filteredGrouped.flatMap(({ bookingId, photos: groupPhotos }) => {
      const booking = bookingMap.get(bookingId)
      return groupPhotos.map((p) => ({
        id: p.id,
        storagePath: p.storagePath,
        kind: p.kind,
        bookingDate: booking ? formatBookingDate(booking.scheduledAt) : undefined,
        serviceName: booking?.serviceName ?? undefined,
        artistName: booking?.artistName ?? undefined,
        caption: p.caption,
      }))
    })
  }, [filteredGrouped, bookingMap])

  // Kind counts for filter toggle
  const kindCounts = useMemo(() => {
    const counts: Partial<Record<PhotoKind, number>> = {}
    for (const p of photos) {
      counts[p.kind] = (counts[p.kind] ?? 0) + 1
    }
    return counts
  }, [photos])

  const handlePhotoClick = useCallback((globalIndex: number) => {
    setLightboxIndex(globalIndex)
    setLightboxOpen(true)
  }, [])

  if (photos.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-4 text-center">
        <div className="rounded-xl bg-muted/50 p-4">
          <ImageIcon className="h-10 w-10 text-muted-foreground/50" />
        </div>
        <div className="space-y-1">
          <h3 className="text-sm font-medium">No photos yet</h3>
          <p className="text-sm text-muted-foreground max-w-xs">
            Photos are uploaded during the booking process and will appear here grouped by appointment.
          </p>
        </div>
      </div>
    )
  }

  // Calculate global offsets per group
  let offset = 0
  const groupsWithOffset = filteredGrouped.map(({ bookingId, photos: groupPhotos }) => {
    const groupOffset = offset
    offset += groupPhotos.length
    return { bookingId, photos: groupPhotos, globalOffset: groupOffset }
  })

  return (
    <div className="space-y-6">
      {/* Kind filter */}
      <div className="flex items-center gap-3">
        <span className="text-xs text-muted-foreground shrink-0">Filter</span>
        <KindFilterToggle
          value={kindFilter}
          onChange={setKindFilter}
          counts={kindCounts}
        />
      </div>

      {/* Empty filtered state */}
      {filteredGrouped.length === 0 && (
        <div className="flex flex-col items-center justify-center py-12 gap-3 text-center">
          <ImageIcon className="h-8 w-8 text-muted-foreground/40" />
          <p className="text-sm text-muted-foreground">No {kindFilter} photos found</p>
        </div>
      )}

      {/* Photo groups */}
      <div className="space-y-8">
        {groupsWithOffset.map(({ bookingId, photos: groupPhotos, globalOffset: gOffset }) => {
          const booking = bookingMap.get(bookingId)
          return (
            <PhotoGroup
              key={bookingId}
              bookingDate={booking ? formatBookingDate(booking.scheduledAt) : 'Unknown date'}
              serviceName={booking?.serviceName}
              artistName={booking?.artistName}
              photos={groupPhotos.map((p) => ({
                id: p.id,
                storagePath: p.storagePath,
                kind: p.kind,
                caption: p.caption,
                bookingDate: booking ? formatBookingDate(booking.scheduledAt) : undefined,
                serviceName: booking?.serviceName ?? undefined,
                artistName: booking?.artistName ?? undefined,
              }))}
              getSignedUrl={getSignedUrl}
              onPhotoClick={handlePhotoClick}
              globalOffset={gOffset}
            />
          )
        })}
      </div>

      {/* Lightbox */}
      <PhotoLightbox
        photos={flatLightboxPhotos}
        initialIndex={lightboxIndex}
        open={lightboxOpen}
        onOpenChange={setLightboxOpen}
        getSignedUrl={getSignedUrl}
      />
    </div>
  )
}

'use client'

import { useState } from 'react'
import {
  FileText,
  FileImage,
  File,
  Download,
  Trash2,
  MoreHorizontal,
  ExternalLink,
} from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { formatBytes, formatRelativeTime } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type ClientFile = Database['public']['Tables']['client_files']['Row']

const KIND_LABELS: Record<ClientFile['kind'], string> = {
  id: 'ID Document',
  medical: 'Medical',
  waiver: 'Waiver',
  health_form: 'Health Form',
  other: 'Other',
}

function FileTypeIcon({ mimeType }: { mimeType: string }) {
  if (mimeType.startsWith('image/')) {
    return <FileImage className="h-4 w-4 text-muted-foreground" />
  }
  if (mimeType === 'application/pdf' || mimeType.includes('document')) {
    return <FileText className="h-4 w-4 text-muted-foreground" />
  }
  return <File className="h-4 w-4 text-muted-foreground" />
}

interface FileRowProps {
  file: ClientFile
  onDelete: (fileId: string) => void
}

export function FileRow({ file, onDelete }: FileRowProps) {
  const [isDownloading, setIsDownloading] = useState(false)

  async function handleDownload() {
    setIsDownloading(true)
    try {
      const res = await fetch(`/api/client-files/${file.id}`)
      if (!res.ok) throw new Error('Failed to get download URL')
      const json = await res.json() as { url: string }
      const a = document.createElement('a')
      a.href = json.url
      a.download = file.file_name
      a.target = '_blank'
      a.click()
    } catch {
      toast.error('Failed to download file')
    } finally {
      setIsDownloading(false)
    }
  }

  async function handleViewInTab() {
    try {
      const res = await fetch(`/api/client-files/${file.id}`)
      if (!res.ok) throw new Error('Failed to get URL')
      const json = await res.json() as { url: string }
      window.open(json.url, '_blank', 'noopener,noreferrer')
    } catch {
      toast.error('Failed to open file')
    }
  }

  const uploadedAt = formatRelativeTime(new Date(file.created_at))

  return (
    <div className="flex items-center gap-3 px-4 py-3 rounded-lg border border-border/40 bg-card hover:border-border/60 transition-colors">
      <div className="shrink-0">
        <FileTypeIcon mimeType={file.mime_type} />
      </div>

      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium truncate">{file.file_name}</p>
        <p className="text-xs text-muted-foreground tabular-nums">
          {KIND_LABELS[file.kind]} · {formatBytes(file.size_bytes)} · {uploadedAt}
        </p>
      </div>

      {file.expires_at && (
        <span className="text-[10px] text-amber-500 shrink-0">
          Expires {new Date(file.expires_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
        </span>
      )}

      <div className="flex items-center gap-1 shrink-0">
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8"
          onClick={handleDownload}
          disabled={isDownloading}
          aria-label="Download file"
        >
          <Download className="h-3.5 w-3.5" />
        </Button>

        <DropdownMenu>
          <DropdownMenuTrigger render={
            <Button variant="ghost" size="icon" className="h-8 w-8">
              <MoreHorizontal className="h-3.5 w-3.5" />
