'use client'

import { useState, useRef } from 'react'
import { UploadCloud, X, File } from 'lucide-react'
import { toast } from 'sonner'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Progress } from '@/components/ui/progress'
import { cn } from '@/lib/utils'
import { formatBytes } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type FileKind = Database['public']['Tables']['client_files']['Row']['kind']

const KINDS: { value: FileKind; label: string }[] = [
  { value: 'id', label: 'ID Document' },
  { value: 'medical', label: 'Medical' },
  { value: 'waiver', label: 'Waiver' },
  { value: 'health_form', label: 'Health Form' },
  { value: 'other', label: 'Other' },
]

const ACCEPTED_MIME = [
  'image/jpeg',
  'image/png',
  'image/webp',
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
]
const MAX_SIZE_BYTES = 20 * 1024 * 1024 // 20MB

interface FileUploaderProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  clientId: string
  onSuccess: () => void
}

export function FileUploader({ open, onOpenChange, clientId, onSuccess }: FileUploaderProps) {
  const [file, setFile] = useState<File | null>(null)
  const [kind, setKind] = useState<FileKind>('other')
  const [uploading, setUploading] = useState(false)
  const [progress, setProgress] = useState(0)
  const [dragOver, setDragOver] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  function validateFile(f: File): string | null {
    if (!ACCEPTED_MIME.includes(f.type)) {
      return 'File type not supported. Use JPG, PNG, WebP, PDF, or Word documents.'
    }
    if (f.size > MAX_SIZE_BYTES) {
      return `File is too large (${formatBytes(f.size)}). Maximum is 20 MB.`
    }
    return null
  }

  function handleFileSelect(f: File) {
    const error = validateFile(f)
    if (error) {
      toast.error(error)
      return
    }
    setFile(f)
  }

  function handleDrop(e: React.DragEvent<HTMLDivElement>) {
    e.preventDefault()
    setDragOver(false)
    const dropped = e.dataTransfer.files[0]
    if (dropped) handleFileSelect(dropped)
  }

  async function handleUpload() {
    if (!file) return
    setUploading(true)
    setProgress(0)

    const formData = new FormData()
    formData.append('file', file)
    formData.append('client_id', clientId)
    formData.append('kind', kind)

    try {
      // Use XMLHttpRequest for progress tracking
      await new Promise<void>((resolve, reject) => {
        const xhr = new XMLHttpRequest()
        xhr.upload.onprogress = (e) => {
          if (e.lengthComputable) {
            setProgress(Math.round((e.loaded / e.total) * 100))
          }
        }
        xhr.onload = () => {
          if (xhr.status >= 200 && xhr.status < 300) {
            resolve()
          } else {
            const json = JSON.parse(xhr.responseText) as { error?: string }
            reject(new Error(json.error ?? 'Upload failed'))
          }
        }
        xhr.onerror = () => reject(new Error('Network error'))
        xhr.open('POST', '/api/client-files')
        xhr.send(formData)
      })

      toast.success('File uploaded')
      setFile(null)
      setKind('other')
      setProgress(0)
      onOpenChange(false)
      onSuccess()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Upload failed'
      toast.error(message)
    } finally {
      setUploading(false)
    }
  }

  function handleClose() {
    if (uploading) return
    setFile(null)
    setKind('other')
    setProgress(0)
    onOpenChange(false)
  }

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-[480px]">
        <DialogHeader>
          <DialogTitle>Upload file</DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Drop zone */}
          <div
            className={cn(
              'relative border-2 border-dashed rounded-lg p-8 text-center transition-colors',
              dragOver ? 'border-primary bg-primary/5' : 'border-border/60 hover:border-border',
              file && 'border-primary/40 bg-primary/5'
            )}
            onDragOver={(e) => { e.preventDefault(); setDragOver(true) }}
            onDragLeave={() => setDragOver(false)}
            onDrop={handleDrop}
          >
            {file ? (
              <div className="flex items-center gap-3">
                <File className="h-8 w-8 text-primary shrink-0" />
                <div className="flex-1 min-w-0 text-left">
                  <p className="text-sm font-medium truncate">{file.name}</p>
                  <p className="text-xs text-muted-foreground">{formatBytes(file.size)}</p>
                </div>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-7 w-7 shrink-0"
                  onClick={() => setFile(null)}
                  disabled={uploading}
                >
                  <X className="h-4 w-4" />
                  <span className="sr-only">Remove file</span>
                </Button>
              </div>
            ) : (
              <div className="flex flex-col items-center gap-2">
                <UploadCloud className="h-8 w-8 text-muted-foreground/50" />
                <div>
                  <p className="text-sm font-medium">Drop file here or</p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    JPG, PNG, WebP, PDF, Word · Max 20 MB
                  </p>
                </div>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => inputRef.current?.click()}
                  disabled={uploading}
                >
                  Browse
                </Button>
              </div>
            )}
            <input
              ref={inputRef}
              type="file"
              className="sr-only"
              accept={ACCEPTED_MIME.join(',')}
              onChange={(e) => {
                const f = e.target.files?.[0]
                if (f) handleFileSelect(f)
                e.target.value = ''
              }}
            />
          </div>

          {/* Kind selector */}
          <div className="space-y-1.5">
            <Label htmlFor="file-kind">File type</Label>
            <Select value={kind} onValueChange={(v) => setKind(v as FileKind)}>
              <SelectTrigger id="file-kind">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {KINDS.map((k) => (
                  <SelectItem key={k.value} value={k.value}>
                    {k.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Upload progress */}
          {uploading && (
            <div className="space-y-1.5">
              <div className="flex justify-between text-xs text-muted-foreground">
                <span>Uploading…</span>
                <span className="tabular-nums">{progress}%</span>
              </div>
              <Progress value={progress} className="h-1.5" />
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={handleClose} disabled={uploading}>
            Cancel
          </Button>
          <Button onClick={handleUpload} disabled={!file || uploading}>
            {uploading ? 'Uploading…' : 'Upload'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState, useCallback } from 'react'
import { Plus, FolderOpen } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { FileRow } from './FileRow'
import { FileUploader } from './FileUploader'
import type { Database } from '@/lib/supabase/types'

type ClientFile = Database['public']['Tables']['client_files']['Row']

interface ClientFilesTabProps {
  clientId: string
  initialFiles: ClientFile[]
}

export function ClientFilesTab({ clientId, initialFiles }: ClientFilesTabProps) {
  const [files, setFiles] = useState<ClientFile[]>(initialFiles)
  const [uploadOpen, setUploadOpen] = useState(false)
  const [loading, setLoading] = useState(false)

  const refetch = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch(`/api/client-files?client_id=${clientId}`)
      if (res.ok) {
        const json = await res.json() as { data: ClientFile[] }
        setFiles(json.data ?? [])
      }
    } finally {
      setLoading(false)
    }
  }, [clientId])

  async function handleDelete(fileId: string) {
    const res = await fetch(`/api/client-files/${fileId}`, { method: 'DELETE' })
    if (!res.ok) {
      toast.error('Failed to delete file')
      return
    }
    toast.success('File deleted')
    setFiles((prev) => prev.filter((f) => f.id !== fileId))
  }

  const sortedFiles = [...files].sort((a, b) => b.created_at.localeCompare(a.created_at))

  return (
    <div className="flex flex-col gap-4">
      <div className="flex items-center justify-between">
        <h2 className="text-base font-semibold">Files</h2>
        <Button size="sm" onClick={() => setUploadOpen(true)}>
          <Plus className="mr-2 h-4 w-4" />
          Upload file
        </Button>
      </div>

      {loading ? (
        <div className="space-y-2">
          {[1, 2, 3].map((i) => (
            <Skeleton key={i} className="h-16 w-full rounded-lg" />
          ))}
        </div>
      ) : files.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 gap-4 text-center">
          <div className="rounded-xl bg-muted/50 p-4">
            <FolderOpen className="h-10 w-10 text-muted-foreground/50" />
          </div>
          <div className="space-y-1">
            <h3 className="text-sm font-medium">No files yet</h3>
            <p className="text-sm text-muted-foreground max-w-xs">
              Upload ID documents, waivers, health forms, and other client files here.
            </p>
          </div>
          <Button size="sm" onClick={() => setUploadOpen(true)}>
            <Plus className="mr-2 h-4 w-4" />
            Upload file
          </Button>
        </div>
      ) : (
        <div className="space-y-2">
          {sortedFiles.map((file) => (
            <FileRow key={file.id} file={file} onDelete={handleDelete} />
          ))}
        </div>
      )}

      <FileUploader
        open={uploadOpen}
        onOpenChange={setUploadOpen}
        clientId={clientId}
        onSuccess={refetch}
      />
    </div>
  )
}

