type ConsentPrefs = Database['public']['Tables']['client_consent_preferences']['Row']

const CONSENT_FIELDS: {
  key: keyof Pick<
    ConsentPrefs,
    'marketing_email' | 'marketing_sms' | 'transactional_only' | 'photo_use_portfolio' | 'photo_use_social'
  >
