interface ClientConsentTabProps {
  clientId: string
  initialPrefs: ConsentPrefs | null
}

export function ClientConsentTab({ clientId, initialPrefs }: ClientConsentTabProps) {
  const defaultPrefs: Partial<ConsentPrefs> = {
    marketing_email: false,
    marketing_sms: false,
    transactional_only: false,
    photo_use_portfolio: false,
    photo_use_social: false,
    data_retention_years: 7,
    consent_version: 1,
  }

  const [prefs, setPrefs] = useState<Partial<ConsentPrefs>>(initialPrefs ?? defaultPrefs)
  const [saving, setSaving] = useState(false)
  const [isDirty, setIsDirty] = useState(false)

  function handleToggle(key: keyof typeof defaultPrefs, value: boolean) {
    setPrefs((prev) => ({ ...prev, [key]: value }))
    setIsDirty(true)
  }

  async function handleSave() {
    setSaving(true)
    try {
      const res = await fetch(`/api/client-consent/${clientId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          marketing_email: prefs.marketing_email ?? false,
          marketing_sms: prefs.marketing_sms ?? false,
          transactional_only: prefs.transactional_only ?? false,
          photo_use_portfolio: prefs.photo_use_portfolio ?? false,
          photo_use_social: prefs.photo_use_social ?? false,
          data_retention_years: prefs.data_retention_years ?? 7,
        }),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to save')
      }
      const json = await res.json() as { data: ConsentPrefs }
      setPrefs(json.data)
      setIsDirty(false)
      toast.success('Consent preferences saved')
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to save consent preferences'
      toast.error(message)
    } finally {
      setSaving(false)
    }
  }

  const marketingFields = CONSENT_FIELDS.filter((f) => f.section === 'marketing')
  const photoFields = CONSENT_FIELDS.filter((f) => f.section === 'photos')

  return (
    <div className="flex flex-col gap-6 max-w-xl">
      {/* Header */}
      <div className="flex items-start gap-3">
        <div className="rounded-lg bg-muted/50 p-2 mt-0.5">
          <ShieldCheck className="h-5 w-5 text-muted-foreground" />
        </div>
        <div>
          <h2 className="text-base font-semibold">Consent & GDPR preferences</h2>
          <p className="text-sm text-muted-foreground mt-0.5">
            Manage this client's data usage and communication preferences.
          </p>
        </div>
      </div>

      {/* Marketing section */}
      <div className="space-y-4">
        <h3 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
          Marketing communications
        </h3>
        <div className="space-y-4">
          {marketingFields.map((field) => (
            <div key={field.key} className="flex items-start justify-between gap-4">
              <div className="flex-1 min-w-0">
                <Label htmlFor={`consent-${field.key}`} className="text-sm font-medium cursor-pointer">
                  {field.label}
                </Label>
                <p className="text-xs text-muted-foreground mt-0.5 leading-relaxed">
                  {field.description}
                </p>
              </div>
              <Switch
                id={`consent-${field.key}`}
                checked={Boolean(prefs[field.key])}
                onCheckedChange={(v) => handleToggle(field.key, v)}
              />
            </div>
          ))}
        </div>
      </div>

      {/* Divider */}
      <div className="h-px bg-border/40" />

      {/* Photos section */}
      <div className="space-y-4">
        <h3 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
          Photo usage
        </h3>
        <div className="space-y-4">
          {photoFields.map((field) => (
            <div key={field.key} className="flex items-start justify-between gap-4">
              <div className="flex-1 min-w-0">
                <Label htmlFor={`consent-${field.key}`} className="text-sm font-medium cursor-pointer">
                  {field.label}
                </Label>
                <p className="text-xs text-muted-foreground mt-0.5 leading-relaxed">
                  {field.description}
                </p>
              </div>
              <Switch
                id={`consent-${field.key}`}
                checked={Boolean(prefs[field.key])}
                onCheckedChange={(v) => handleToggle(field.key, v)}
              />
            </div>
          ))}
        </div>
      </div>

      {/* Version info */}
      {initialPrefs && (
        <div className="rounded-lg border border-border/40 bg-muted/20 px-4 py-3">
          <div className="flex items-center justify-between text-xs text-muted-foreground">
            <span>Consent version {initialPrefs.consent_version}</span>
            {initialPrefs.consented_at && (
              <span className="tabular-nums">
                Last updated {new Date(initialPrefs.consented_at).toLocaleDateString('en-US', {
                  month: 'short',
                  day: 'numeric',
                  year: 'numeric',
                })}
              </span>
            )}
          </div>
        </div>
      )}

      {/* Save button */}
      <div className="flex justify-end">
        <Button onClick={handleSave} disabled={!isDirty || saving}>
          {saving ? 'Saving…' : 'Save preferences'}
        </Button>
      </div>
    </div>
  )
}

'use client'

import { DollarSign, TrendingUp, Calendar, Award } from 'lucide-react'
import { formatCurrency, formatRelativeTime } from '@/lib/utils'
import { Skeleton } from '@/components/ui/skeleton'
import type { Database } from '@/lib/supabase/types'

type Client = Database['public']['Tables']['clients']['Row']
type Booking = Database['public']['Tables']['bookings']['Row'] & {
  services?: { name: string } | null
  artists?: { display_name: string } | null
}

const STATUS_LABELS: Record<Booking['status'], string> = {
  pending: 'Pending',
  confirmed: 'Confirmed',
  in_progress: 'In progress',
  completed: 'Completed',
  cancelled: 'Cancelled',
  no_show: 'No-show',
}

const STATUS_DOT: Record<Booking['status'], string> = {
  pending: 'bg-amber-500',
  confirmed: 'bg-blue-500',
  in_progress: 'bg-purple-500',
  completed: 'bg-emerald-500',
  cancelled: 'bg-muted-foreground',
  no_show: 'bg-destructive',
}

interface FinancialStatCardProps {
  label: string
  value: string
  sublabel?: string
  icon: React.ComponentType<{ className?: string }>
}

function FinancialStatCard({ label, value, sublabel, icon: Icon }: FinancialStatCardProps) {
  return (
    <div className="flex items-start gap-3 p-4 rounded-lg border border-border/40 bg-card">
      <div className="rounded-md bg-muted/50 p-2 mt-0.5 shrink-0">
        <Icon className="h-4 w-4 text-muted-foreground" />
      </div>
      <div>
        <p className="text-xl font-bold tabular-nums">{value}</p>
        <p className="text-xs font-medium text-muted-foreground">{label}</p>
        {sublabel && (
          <p className="text-[11px] text-muted-foreground mt-0.5">{sublabel}</p>
        )}
      </div>
    </div>
  )
}

interface ClientFinancialTabProps {
  client: Client
  sessions: Booking[]
}

export function ClientFinancialTab({ client, sessions }: ClientFinancialTabProps) {
  const completedSessions = sessions.filter((s) => s.status === 'completed')
  const avgSessionValue = completedSessions.length > 0
    ? Math.round(client.lifetime_value_cents / completedSessions.length)
    : 0

  const sortedSessions = [...sessions].sort((a, b) =>
    b.scheduled_at.localeCompare(a.scheduled_at)
  )

  return (
    <div className="flex flex-col gap-6">
      {/* Stats grid */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <FinancialStatCard
          icon={DollarSign}
          label="Lifetime value"
          value={formatCurrency(client.lifetime_value_cents)}
          sublabel={`Total paid to studio`}
        />
        <FinancialStatCard
          icon={TrendingUp}
          label="Avg session value"
          value={formatCurrency(avgSessionValue)}
          sublabel={`Over ${completedSessions.length} sessions`}
        />
        <FinancialStatCard
          icon={Calendar}
          label="Total sessions"
          value={String(client.total_sessions)}
          sublabel={`${client.no_show_count} no-show${client.no_show_count !== 1 ? 's' : ''}`}
        />
        <FinancialStatCard
          icon={Award}
          label="Loyalty points"
          value={client.loyalty_points.toLocaleString()}
          sublabel="Current balance"
        />
      </div>

      {/* Sessions table */}
      <div className="space-y-3">
        <h3 className="text-sm font-semibold">Session history</h3>

        {sessions.length === 0 ? (
          <div className="text-center py-10">
            <p className="text-sm text-muted-foreground">No sessions on record yet</p>
          </div>
        ) : (
          <div className="rounded-lg border border-border/40 overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-border/40 bg-muted/30">
                  <th className="text-left px-4 py-2.5 text-xs font-semibold text-muted-foreground">Date</th>
                  <th className="text-left px-4 py-2.5 text-xs font-semibold text-muted-foreground">Service</th>
                  <th className="text-left px-4 py-2.5 text-xs font-semibold text-muted-foreground hidden sm:table-cell">Artist</th>
                  <th className="text-left px-4 py-2.5 text-xs font-semibold text-muted-foreground">Status</th>
                  <th className="text-right px-4 py-2.5 text-xs font-semibold text-muted-foreground tabular-nums">Amount</th>
                </tr>
              </thead>
              <tbody>
                {sortedSessions.map((session, idx) => {
                  const isLast = idx === sortedSessions.length - 1
                  const sessionDate = new Date(session.scheduled_at).toLocaleDateString('en-US', {
                    month: 'short',
                    day: 'numeric',
                    year: 'numeric',
                  })
                  const total = session.price_cents + session.tip_cents

                  return (
                    <tr
                      key={session.id}
                      className={!isLast ? 'border-b border-border/30' : ''}
                    >
                      <td className="px-4 py-3 text-xs text-muted-foreground tabular-nums whitespace-nowrap">
                        {sessionDate}
                      </td>
                      <td className="px-4 py-3 text-sm">
                        {(session as Booking & { services?: { name: string } | null }).services?.name ?? 'Session'}
                      </td>
                      <td className="px-4 py-3 text-sm text-muted-foreground hidden sm:table-cell">
                        {(session as Booking & { artists?: { display_name: string } | null }).artists?.display_name ?? '—'}
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-1.5">
                          <span className={`h-1.5 w-1.5 rounded-full ${STATUS_DOT[session.status]}`} />
                          <span className="text-xs">{STATUS_LABELS[session.status]}</span>
                        </div>
                      </td>
                      <td className="px-4 py-3 text-sm font-medium tabular-nums text-right">
                        {total > 0 ? formatCurrency(total) : '—'}
                        {session.tip_cents > 0 && (
                          <span className="text-[10px] text-muted-foreground ml-1">
                            (+{formatCurrency(session.tip_cents)} tip)
                          </span>
                        )}
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  )
}

