213	storage_path TEXT
214	file_size_bytes INT
215	mime_type TEXT
216	uploaded_by FK → profiles
217	created_at TIMESTAMPTZ
218	```
219	
220	### `communications_log`
221	```
222	id uuid PK
223	studio_id FK
224	client_id FK
225	channel TEXT       -- sms|email|whatsapp
226	direction TEXT     -- outbound (Sprint 3 only shows outbound)
227	template_id TEXT   -- nullable (if sent from template)
228	subject TEXT       -- email subject or SMS first 80 chars
229	body TEXT
230	status TEXT        -- queued|sent|delivered|opened|failed
231	provider_ref TEXT  -- external message ID
232	sent_at TIMESTAMPTZ
233	delivered_at TIMESTAMPTZ
234	opened_at TIMESTAMPTZ
235	created_at TIMESTAMPTZ
236	```
237	
238	### `clients` column additions (ALTER TABLE)
239	```sql
240	ALTER TABLE clients ADD COLUMN IF NOT EXISTS preferred_contact TEXT DEFAULT 'email';
241	ALTER TABLE clients ADD COLUMN IF NOT EXISTS consent_marketing BOOLEAN NOT NULL DEFAULT false;
242	ALTER TABLE clients ADD COLUMN IF NOT EXISTS consent_sms       BOOLEAN NOT NULL DEFAULT false;
243	ALTER TABLE clients ADD COLUMN IF NOT EXISTS consent_gdpr_date TIMESTAMPTZ;
244	ALTER TABLE clients ADD COLUMN IF NOT EXISTS emergency_contact JSONB;  -- {name, phone, relationship}
245	ALTER TABLE clients ADD COLUMN IF NOT EXISTS archived_at       TIMESTAMPTZ;
246	```
