'use client'

import { useState, useEffect } from 'react'
import { toast } from 'sonner'
import { differenceInYears } from 'date-fns'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Checkbox } from '@/components/ui/checkbox'
import { Badge } from '@/components/ui/badge'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { TagPicker } from './TagPicker'
import type { ClientTag } from './TagChip'
import type { Database } from '@/lib/supabase/types'

type Client = Database['public']['Tables']['clients']['Row']

interface ClientDrawerProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  client?: Client | null
  tagLibrary: ClientTag[]
  onSuccess: (client: Client) => void
}

type FormData = {
  // Section 1: Basics
  first_name: string
  last_name: string
  email: string
  phone: string
  date_of_birth: string
  // Section 2: Address
  address_line1: string
  address_line2: string
  address_city: string
  address_state: string
  address_zip: string
  address_country: string
  // Section 3: Tags & Source
  tags: string[]
  source: string
  referral_source: string
  preferred_contact: 'email' | 'sms' | 'phone' | 'whatsapp'
  // Section 4: Notes
  notes: string
  // Section 5: Consent
  consent_minor: boolean
}

const PREFERRED_CONTACT_OPTIONS = [
  { value: 'email', label: 'Email' },
  { value: 'sms', label: 'SMS' },
  { value: 'phone', label: 'Phone' },
  { value: 'whatsapp', label: 'WhatsApp' },
] as const

const SOURCE_OPTIONS = [
  { value: '', label: 'Unknown' },
  { value: 'public_booking', label: 'Booking page' },
  { value: 'walk_in', label: 'Walk-in' },
  { value: 'referral', label: 'Referral' },
  { value: 'social_media', label: 'Social media' },
  { value: 'manual', label: 'Manual entry' },
]

function SectionHeader({ title }: { title: string }) {
  return (
    <div className="flex items-center gap-2 pt-2">
      <h3 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
        {title}
      </h3>
      <div className="h-px flex-1 bg-border/40" />
    </div>
  )
}

export function ClientDrawer({ open, onOpenChange, client, tagLibrary, onSuccess }: ClientDrawerProps) {
  const isEditing = Boolean(client)

  // Parse existing address
  const existingAddress = (() => {
    if (!client?.address) return {}
    if (typeof client.address === 'object' && !Array.isArray(client.address)) {
      return client.address as Record<string, string>
    }
    return {}
  })()

  const [form, setForm] = useState<FormData>({
    first_name: client?.first_name ?? '',
    last_name: client?.last_name ?? '',
    email: client?.email ?? '',
    phone: client?.phone ?? '',
    date_of_birth: client?.date_of_birth ?? '',
    address_line1: (existingAddress.line1 as string) ?? '',
    address_line2: (existingAddress.line2 as string) ?? '',
    address_city: (existingAddress.city as string) ?? '',
    address_state: (existingAddress.state as string) ?? '',
    address_zip: (existingAddress.zip as string) ?? '',
    address_country: (existingAddress.country as string) ?? '',
    tags: client?.tags ?? [],
    source: client?.source ?? '',
    referral_source: client?.referral_source ?? '',
    preferred_contact: client?.preferred_contact ?? 'email',
    notes: client?.notes ?? '',
    consent_minor: client?.consent_minor ?? false,
  })

  const [errors, setErrors] = useState<Partial<Record<keyof FormData, string>>>({})
  const [saving, setSaving] = useState(false)

  // Reset form when client changes
  useEffect(() => {
    if (open) {
      const addr = (() => {
        if (!client?.address) return {}
        if (typeof client.address === 'object' && !Array.isArray(client.address)) {
          return client.address as Record<string, string>
        }
        return {}
      })()

      setForm({
        first_name: client?.first_name ?? '',
        last_name: client?.last_name ?? '',
        email: client?.email ?? '',
        phone: client?.phone ?? '',
        date_of_birth: client?.date_of_birth ?? '',
        address_line1: (addr.line1 as string) ?? '',
        address_line2: (addr.line2 as string) ?? '',
        address_city: (addr.city as string) ?? '',
        address_state: (addr.state as string) ?? '',
        address_zip: (addr.zip as string) ?? '',
        address_country: (addr.country as string) ?? '',
        tags: client?.tags ?? [],
        source: client?.source ?? '',
        referral_source: client?.referral_source ?? '',
        preferred_contact: client?.preferred_contact ?? 'email',
        notes: client?.notes ?? '',
        consent_minor: client?.consent_minor ?? false,
      })
      setErrors({})
    }
  }, [open, client])

  // Auto-compute consent_minor from DOB
  useEffect(() => {
    if (form.date_of_birth) {
      try {
        const dob = new Date(form.date_of_birth)
        const isMinor = differenceInYears(new Date(), dob) < 18
        setForm((prev) => ({ ...prev, consent_minor: isMinor }))
      } catch {
        // ignore invalid date
      }
    }
  }, [form.date_of_birth])

  function set<K extends keyof FormData>(key: K, value: FormData[K]) {
    setForm((prev) => ({ ...prev, [key]: value }))
    if (errors[key]) setErrors((prev) => ({ ...prev, [key]: undefined }))
  }

  function validate(): boolean {
    const newErrors: Partial<Record<keyof FormData, string>> = {}
    if (!form.first_name.trim()) newErrors.first_name = 'First name is required'
    if (form.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) {
      newErrors.email = 'Enter a valid email address'
    }
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  async function handleSave() {
    if (!validate()) return
    setSaving(true)

    const address = {
      line1: form.address_line1,
      line2: form.address_line2,
      city: form.address_city,
      state: form.address_state,
      zip: form.address_zip,
      country: form.address_country,
    }

    const payload = {
      first_name: form.first_name.trim(),
      last_name: form.last_name.trim() || null,
      email: form.email.trim() || null,
      phone: form.phone.trim() || null,
      date_of_birth: form.date_of_birth || null,
      address: Object.values(address).some(Boolean) ? address : null,
      tags: form.tags,
      source: form.source || null,
      referral_source: form.referral_source.trim() || null,
      preferred_contact: form.preferred_contact,
      notes: form.notes.trim() || null,
      consent_minor: form.consent_minor,
    }

    try {
      const res = await fetch(
        isEditing ? `/api/clients/${client!.id}` : '/api/clients',
        {
          method: isEditing ? 'PATCH' : 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        }
      )

      if (!res.ok) {
        const json = await res.json() as { error?: string }
        if (res.status === 409) {
          setErrors({ email: json.error ?? 'Email already in use' })
          return
        }
        throw new Error(json.error ?? 'Failed to save client')
      }

      const json = await res.json() as { data: Client }
      toast.success(isEditing ? 'Client updated' : 'Client added')
      onOpenChange(false)
      onSuccess(json.data)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to save client'
      toast.error(message)
    } finally {
      setSaving(false)
    }
  }

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent side="right" className="w-full max-w-[520px] overflow-y-auto flex flex-col">
        <SheetHeader className="pb-4 shrink-0">
          <SheetTitle>{isEditing ? 'Edit client' : 'New client'}</SheetTitle>
        </SheetHeader>

        <div className="flex-1 overflow-y-auto space-y-5 pr-0.5">
          {/* Section 1: Basics */}
          <SectionHeader title="Basic info" />

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label htmlFor="client-first-name">
                First name <span className="text-destructive">*</span>
              </Label>
              <Input
                id="client-first-name"
                value={form.first_name}
                onChange={(e) => set('first_name', e.target.value)}
                aria-invalid={Boolean(errors.first_name)}
                aria-describedby={errors.first_name ? 'fn-error' : undefined}
              />
              {errors.first_name && (
                <p id="fn-error" role="alert" className="text-xs text-destructive">{errors.first_name}</p>
              )}
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="client-last-name">Last name</Label>
              <Input
                id="client-last-name"
                value={form.last_name}
                onChange={(e) => set('last_name', e.target.value)}
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="client-email">Email</Label>
            <Input
              id="client-email"
              type="email"
              value={form.email}
              onChange={(e) => set('email', e.target.value)}
              aria-invalid={Boolean(errors.email)}
              aria-describedby={errors.email ? 'email-error' : undefined}
            />
            {errors.email && (
              <p id="email-error" role="alert" className="text-xs text-destructive">{errors.email}</p>
            )}
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label htmlFor="client-phone">Phone</Label>
              <Input
                id="client-phone"
                type="tel"
                value={form.phone}
                onChange={(e) => set('phone', e.target.value)}
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="client-dob">Date of birth</Label>
              <Input
                id="client-dob"
                type="date"
                value={form.date_of_birth}
                onChange={(e) => set('date_of_birth', e.target.value)}
              />
            </div>
          </div>

          {form.consent_minor && (
            <Badge variant="outline" className="text-amber-500 border-amber-500/40 bg-amber-500/10">
              Minor — parent/guardian consent required
            </Badge>
          )}

          <div className="space-y-1.5">
            <Label htmlFor="client-preferred-contact">Preferred contact</Label>
            <Select
              value={form.preferred_contact}
              onValueChange={(v) => set('preferred_contact', v as FormData['preferred_contact'])}
            >
