'use client'

import { useRef } from 'react'
import { Search, Star, Clock, AlertTriangle, Eye, EyeOff, X, Tag } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import { Checkbox } from '@/components/ui/checkbox'
import { TagChip, type ClientTag } from './TagChip'
import { cn } from '@/lib/utils'

export interface ClientFilters {
  q: string
  tags: string[]
  vip: boolean
  inactive: boolean
  noShows: boolean
  showArchived: boolean
  spendingTier: '' | '0-500' | '500-2000' | '2000+'
}

interface ClientFilterBarProps {
  filters: ClientFilters
  onChange: (filters: ClientFilters) => void
  tagLibrary: ClientTag[]
}

const SPENDING_OPTIONS: { value: ClientFilters['spendingTier']; label: string }[] = [
  { value: '', label: 'Any' },
  { value: '0-500', label: '$0 – $500' },
  { value: '500-2000', label: '$500 – $2K' },
  { value: '2000+', label: '$2K+' },
]

export function ClientFilterBar({ filters, onChange, tagLibrary }: ClientFilterBarProps) {
  const searchRef = useRef<HTMLInputElement>(null)
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  function set<K extends keyof ClientFilters>(key: K, value: ClientFilters[K]) {
    onChange({ ...filters, [key]: value })
  }

  function handleSearchChange(e: React.ChangeEvent<HTMLInputElement>) {
    const val = e.target.value
    if (debounceRef.current) clearTimeout(debounceRef.current)
    debounceRef.current = setTimeout(() => {
      set('q', val)
    }, 300)
  }

  function toggleTag(slug: string) {
    const next = filters.tags.includes(slug)
      ? filters.tags.filter((t) => t !== slug)
      : [...filters.tags, slug]
    set('tags', next)
  }

  function clearAll() {
    onChange({
      q: '',
      tags: [],
      vip: false,
      inactive: false,
      noShows: false,
      showArchived: false,
      spendingTier: '',
    })
    if (searchRef.current) searchRef.current.value = ''
  }

  const hasActiveFilters =
    filters.q ||
    filters.tags.length > 0 ||
    filters.vip ||
    filters.inactive ||
    filters.noShows ||
    filters.spendingTier

  const activeChips: { label: string; onRemove: () => void }[] = []
  if (filters.vip) activeChips.push({ label: 'VIP', onRemove: () => set('vip', false) })
  if (filters.inactive) activeChips.push({ label: 'Inactive >90d', onRemove: () => set('inactive', false) })
  if (filters.noShows) activeChips.push({ label: 'No-shows', onRemove: () => set('noShows', false) })
  if (filters.spendingTier) {
    const label = SPENDING_OPTIONS.find((o) => o.value === filters.spendingTier)?.label ?? filters.spendingTier
    activeChips.push({ label: `Spending: ${label}`, onRemove: () => set('spendingTier', '') })
  }
  for (const slug of filters.tags) {
    const tag = tagLibrary.find((t) => t.name === slug || t.id === slug)
    activeChips.push({
      label: tag?.name ?? slug,
      onRemove: () => toggleTag(slug),
    })
  }

  return (
    <div className="flex flex-col gap-3">
      {/* Search + filter controls */}
      <div className="flex flex-wrap items-center gap-2">
        {/* Search */}
        <div className="relative max-w-sm w-full sm:w-auto">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
          <Input
            ref={searchRef}
            defaultValue={filters.q}
            onChange={handleSearchChange}
            placeholder="Search clients…"
            className="h-9 pl-9 text-sm max-w-sm"
          />
        </div>

        {/* Tag filter */}
        <Popover>
          <PopoverTrigger asChild>
            <Button
              variant="outline"
              size="sm"
              className={cn(
                'h-9 gap-1.5',
                filters.tags.length > 0 && 'bg-primary/10 border-primary/20 text-primary'
              )}
            >
              <Tag className="h-3.5 w-3.5" />
              {filters.tags.length > 0 ? `${filters.tags.length} tags` : 'Tags'}
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-[220px] p-0" align="start">
            <Command>
              <CommandInput placeholder="Search tags…" className="h-9" />
              <CommandList>
                <CommandEmpty>No tags found</CommandEmpty>
                <CommandGroup>
                  {tagLibrary.map((tag) => (
                    <CommandItem
                      key={tag.id}
                      onSelect={() => toggleTag(tag.id)}
                      className="flex items-center gap-2"
                    >
                      <Checkbox
                        checked={filters.tags.includes(tag.id)}
                        className="pointer-events-none"
                        aria-hidden
                      />
                      <span className={cn('h-2 w-2 rounded-full shrink-0', `tag-chip-${tag.color}`)} />
                      <span className="flex-1 text-sm">{tag.name}</span>
                    </CommandItem>
                  ))}
                </CommandGroup>
                {filters.tags.length > 0 && (
                  <div className="border-t border-border/40 p-1">
                    <Button
                      variant="ghost"
                      size="sm"
                      className="w-full h-7 text-xs"
                      onClick={() => set('tags', [])}
                    >
                      Clear tags
                    </Button>
                  </div>
                )}
              </CommandList>
            </Command>
          </PopoverContent>
        </Popover>

        {/* VIP toggle */}
        <Button
          variant="outline"
          size="sm"
          className={cn(
            'h-9 gap-1.5',
            filters.vip && 'bg-primary/10 border-primary/20 text-primary'
          )}
          onClick={() => set('vip', !filters.vip)}
        >
          <Star className="h-3.5 w-3.5" />
          VIP
        </Button>

        {/* Spending filter */}
        <Popover>
          <PopoverTrigger asChild>
            <Button
              variant="outline"
              size="sm"
              className={cn(
                'h-9',
                filters.spendingTier && 'bg-primary/10 border-primary/20 text-primary'
              )}
            >
              Spending
              {filters.spendingTier && (
                <span className="ml-1 text-xs opacity-70">
                  {SPENDING_OPTIONS.find((o) => o.value === filters.spendingTier)?.label}
                </span>
              )}
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-[160px] p-1" align="start">
            <div className="space-y-0.5">
              {SPENDING_OPTIONS.map((opt) => (
                <button
                  key={opt.value || '__any'}
                  type="button"
                  className={cn(
                    'w-full text-left text-sm px-2.5 py-1.5 rounded-md hover:bg-muted transition-colors',
                    filters.spendingTier === opt.value && 'bg-primary/10 text-primary'
                  )}
                  onClick={() => set('spendingTier', opt.value)}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </PopoverContent>
        </Popover>

        {/* Inactive toggle */}
        <Button
          variant="outline"
          size="sm"
          className={cn(
            'h-9 gap-1.5',
            filters.inactive && 'bg-primary/10 border-primary/20 text-primary'
          )}
          onClick={() => set('inactive', !filters.inactive)}
        >
          <Clock className="h-3.5 w-3.5" />
          Inactive &gt;90d
        </Button>

        {/* No-shows toggle */}
        <Button
          variant="outline"
          size="sm"
          className={cn(
            'h-9 gap-1.5',
            filters.noShows && 'bg-destructive/10 border-destructive/20 text-destructive'
          )}
          onClick={() => set('noShows', !filters.noShows)}
        >
          <AlertTriangle className="h-3.5 w-3.5" />
          No-shows
        </Button>

        {/* Show archived — right-aligned */}
        <div className="ml-auto">
          <Button
            variant="ghost"
            size="sm"
            className="h-9 gap-1.5 text-muted-foreground"
            onClick={() => set('showArchived', !filters.showArchived)}
          >
            {filters.showArchived ? (
              <EyeOff className="h-3.5 w-3.5" />
            ) : (
              <Eye className="h-3.5 w-3.5" />
            )}
            {filters.showArchived ? 'Hide archived' : 'Show archived'}
          </Button>
        </div>
      </div>

      {/* Active filter chips */}
      {hasActiveFilters && activeChips.length > 0 && (
        <div className="flex flex-wrap items-center gap-1.5">
          {activeChips.map((chip) => (
            <Badge
              key={chip.label}
              variant="secondary"
              className="h-6 px-2.5 text-xs gap-1.5 cursor-pointer hover:opacity-80 pr-1"
              onClick={chip.onRemove}
            >
              {chip.label}
              <X className="h-3 w-3" />
            </Badge>
          ))}
          <Button variant="ghost" size="sm" className="h-6 text-xs" onClick={clearAll}>
            Clear all
          </Button>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { X, Tag, TagX, Download, Archive, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog'
import { Checkbox } from '@/components/ui/checkbox'
import { TagChip, type ClientTag } from './TagChip'
import { cn } from '@/lib/utils'

interface BulkActionsBarProps {
  selectedIds: string[]
  tagLibrary: ClientTag[]
  onClearSelection: () => void
  onArchived: () => void
  onTagsApplied: () => void
}

export function BulkActionsBar({
  selectedIds,
  tagLibrary,
  onClearSelection,
  onArchived,
  onTagsApplied,
}: BulkActionsBarProps) {
  const [addTagIds, setAddTagIds] = useState<string[]>([])
  const [removeTagIds, setRemoveTagIds] = useState<string[]>([])
  const [isArchiving, setIsArchiving] = useState(false)
  const [isTagging, setIsTagging] = useState(false)
  const [isExporting, setIsExporting] = useState(false)

  async function handleApplyTags(action: 'add' | 'remove') {
    const tagSlugs = action === 'add'
      ? tagLibrary.filter((t) => addTagIds.includes(t.id)).map((t) => t.id)
      : tagLibrary.filter((t) => removeTagIds.includes(t.id)).map((t) => t.id)

    if (tagSlugs.length === 0) return
    setIsTagging(true)

    try {
      const res = await fetch('/api/clients/bulk-tag', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ client_ids: selectedIds, tag_slugs: tagSlugs, action }),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to update tags')
      }
      toast.success(`Tags ${action === 'add' ? 'applied' : 'removed'}`)
      if (action === 'add') setAddTagIds([])
      else setRemoveTagIds([])
      onTagsApplied()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update tags'
      toast.error(message)
    } finally {
      setIsTagging(false)
    }
  }

  async function handleArchive() {
    setIsArchiving(true)
    try {
      await Promise.all(
        selectedIds.map((id) =>
          fetch(`/api/clients/${id}`, { method: 'DELETE' })
        )
      )
      toast.success(`${selectedIds.length} client${selectedIds.length !== 1 ? 's' : ''} archived`, {
        action: {
          label: 'Undo',
          onClick: async () => {
            await Promise.all(
              selectedIds.map((id) => fetch(`/api/clients/${id}/restore`, { method: 'POST' }))
            )
            toast.success('Restored')
            onArchived()
          },
        },
      })
      onClearSelection()
      onArchived()
    } catch {
      toast.error('Failed to archive clients')
    } finally {
      setIsArchiving(false)
    }
  }

  async function handleExport() {
    setIsExporting(true)
    const toastId = toast.loading('Preparing export…')
    try {
      const ids = selectedIds.join(',')
      const res = await fetch(`/api/clients/export?ids=${ids}`)
      if (!res.ok) throw new Error('Export failed')
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `clients-${new Date().toISOString().slice(0, 10)}.csv`
      a.click()
      URL.revokeObjectURL(url)
      toast.success('Downloading', { id: toastId })
    } catch {
      toast.error('Export failed', { id: toastId })
    } finally {
      setIsExporting(false)
    }
  }

  if (selectedIds.length === 0) return null

  return (
    <div
      className={cn(
        'flex items-center justify-between gap-3 px-4 py-2.5',
        'bg-primary/[0.08] border border-primary/20 rounded-lg',
        'animate-in fade-in-0 slide-in-from-top-2 duration-150'
      )}
    >
      <div className="flex items-center gap-2">
        <span className="h-2 w-2 rounded-full bg-primary" />
        <span className="text-sm font-medium">
          {selectedIds.length} client{selectedIds.length !== 1 ? 's' : ''} selected
        </span>
      </div>

      <div className="flex items-center gap-1.5">
        {/* Apply tag */}
        <Popover>
          <PopoverTrigger asChild>
            <Button variant="outline" size="sm" className="h-8 gap-1.5" disabled={isTagging}>
              <Tag className="h-3.5 w-3.5" />
              Add tag
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-[220px] p-0" align="end">
            <Command>
              <CommandInput placeholder="Search tags…" className="h-8" />
              <CommandList>
                <CommandEmpty>No tags found</CommandEmpty>
                <CommandGroup>
                  {tagLibrary.map((tag) => (
                    <CommandItem
                      key={tag.id}
                      onSelect={() =>
                        setAddTagIds((prev) =>
                          prev.includes(tag.id) ? prev.filter((id) => id !== tag.id) : [...prev, tag.id]
                        )
                      }
                    >
                      <Checkbox checked={addTagIds.includes(tag.id)} className="mr-2 pointer-events-none" aria-hidden />
                      <TagChip tag={tag} size="sm" />
                    </CommandItem>
                  ))}
                </CommandGroup>
              </CommandList>
              {addTagIds.length > 0 && (
                <div className="border-t border-border/40 p-2">
                  <Button
                    size="sm"
                    className="w-full h-7"
                    onClick={() => handleApplyTags('add')}
                    disabled={isTagging}
                  >
                    {isTagging ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : 'Apply tags'}
                  </Button>
                </div>
              )}
            </Command>
          </PopoverContent>
        </Popover>

        {/* Remove tag */}
        <Popover>
          <PopoverTrigger asChild>
            <Button variant="outline" size="sm" className="h-8 gap-1.5" disabled={isTagging}>
              <TagX className="h-3.5 w-3.5" />
              Remove tag
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-[220px] p-0" align="end">
            <Command>
              <CommandInput placeholder="Search tags…" className="h-8" />
              <CommandList>
                <CommandEmpty>No tags found</CommandEmpty>
                <CommandGroup>
                  {tagLibrary.map((tag) => (
                    <CommandItem
                      key={tag.id}
                      onSelect={() =>
                        setRemoveTagIds((prev) =>
                          prev.includes(tag.id) ? prev.filter((id) => id !== tag.id) : [...prev, tag.id]
                        )
                      }
                    >
                      <Checkbox checked={removeTagIds.includes(tag.id)} className="mr-2 pointer-events-none" aria-hidden />
                      <TagChip tag={tag} size="sm" />
                    </CommandItem>
                  ))}
                </CommandGroup>
              </CommandList>
              {removeTagIds.length > 0 && (
                <div className="border-t border-border/40 p-2">
                  <Button
                    size="sm"
                    variant="destructive"
                    className="w-full h-7"
                    onClick={() => handleApplyTags('remove')}
                    disabled={isTagging}
                  >
                    {isTagging ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : 'Remove tags'}
                  </Button>
                </div>
              )}
            </Command>
          </PopoverContent>
        </Popover>

        {/* Export */}
        <Button
          variant="outline"
          size="sm"
          className="h-8 gap-1.5"
          onClick={handleExport}
          disabled={isExporting}
        >
          {isExporting ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Download className="h-3.5 w-3.5" />}
          Export CSV
        </Button>

        {/* Archive */}
        <AlertDialog>
          <AlertDialogTrigger asChild>
            <Button variant="outline" size="sm" className="h-8 gap-1.5" disabled={isArchiving}>
              <Archive className="h-3.5 w-3.5" />
              Archive
            </Button>
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Archive {selectedIds.length} client{selectedIds.length !== 1 ? 's' : ''}?</AlertDialogTitle>
              <AlertDialogDescription>
                They will be hidden from your client list and won&apos;t appear in new bookings. You can restore them from the archived view.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction
                onClick={handleArchive}
                className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              >
                {isArchiving ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Archive'}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>

        {/* Clear selection */}
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8"
          onClick={onClearSelection}
          aria-label="Clear selection"
        >
          <X className="h-4 w-4" />
        </Button>
      </div>
    </div>
  )
}

