  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { TagChip, resolveTagSlugs, type ClientTag } from './TagChip'
import { formatCurrency, formatRelativeTime, cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type Client = Database['public']['Tables']['clients']['Row']

const CONTACT_ICON: Record<string, React.ComponentType<{ className?: string }>> = {
  email: Mail,
  sms: Phone,
  phone: Phone,
  whatsapp: MessageCircle,
}

function ContactIcon({ method, value }: { method: string | null; value: string | null | undefined }) {
  if (!method || !value) return null
  const Icon = CONTACT_ICON[method] ?? Mail
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <span>
          <Icon className="h-3.5 w-3.5 text-muted-foreground" />
        </span>
      </TooltipTrigger>
      <TooltipContent>{value}</TooltipContent>
    </Tooltip>
  )
}

function ClientRow({
  client,
  tagLibrary,
  isSelected,
  onSelect,
  onEdit,
  onAddNote,
}: {
  client: Client
  tagLibrary: ClientTag[]
  isSelected: boolean
  onSelect: (id: string, checked: boolean) => void
  onEdit: (client: Client) => void
  onAddNote: (clientId: string) => void
}) {
  const router = useRouter()
  const [isArchiving, setIsArchiving] = useState(false)

  const resolvedTags = resolveTagSlugs(client.tags, tagLibrary)
  const maxTags = 3
  const visibleTags = resolvedTags.slice(0, maxTags)
  const overflow = resolvedTags.length - maxTags

  const lastVisit = client.last_visit_at
    ? formatRelativeTime(new Date(client.last_visit_at))
    : 'Never'

  const daysSinceVisit = client.last_visit_at
    ? (Date.now() - new Date(client.last_visit_at).getTime()) / (1000 * 60 * 60 * 24)
    : Infinity
  const isInactive = daysSinceVisit > 90

  const isArchived = Boolean(client.archived_at)

  async function handleArchive(e: React.MouseEvent) {
    e.stopPropagation()
    setIsArchiving(true)
    try {
      const res = await fetch(`/api/clients/${client.id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to archive')
      toast.success('Client archived', {
        action: {
          label: 'Undo',
          onClick: async () => {
            await fetch(`/api/clients/${client.id}/restore`, { method: 'POST' })
            router.refresh()
          },
        },
      })
      router.refresh()
    } catch {
      toast.error('Failed to archive client')
    } finally {
      setIsArchiving(false)
    }
  }

  const firstName = client.first_name
  const lastName = client.last_name ?? ''
  const initials = `${firstName[0] ?? '?'}${lastName[0] ?? ''}`.toUpperCase()

  return (
    <tr
      className={cn(
        'border-b border-border/30 hover:bg-muted/20 transition-colors cursor-pointer',
        isInactive && 'client-row-inactive',
        isArchived && 'client-row-archived'
      )}
      onClick={() => router.push(`/clients/${client.id}`)}
    >
      {/* Checkbox */}
      <td className="w-10 pl-4 py-3" onClick={(e) => e.stopPropagation()}>
        <Checkbox
          checked={isSelected}
          onCheckedChange={(v) => onSelect(client.id, Boolean(v))}
          aria-label={`Select ${firstName} ${lastName}`}
        />
      </td>

      {/* Client name + phone */}
      <td className="py-3 pr-4">
        <div className="flex items-center gap-3">
          <div className="client-avatar-hero h-8 w-8 rounded-full flex items-center justify-center text-white text-xs font-semibold shrink-0 tabular-nums">
            {initials}
          </div>
          <div className="min-w-0">
            <p className="client-name text-sm font-medium truncate">
              {firstName} {lastName}
            </p>
            {client.phone && (
              <p className="text-xs text-muted-foreground tabular-nums">{client.phone}</p>
            )}
          </div>
        </div>
      </td>

      {/* Tags */}
      <td className="py-3 pr-4 w-44">
        <div className="flex flex-wrap gap-1">
          {visibleTags.map((tag) => (
            <TagChip key={tag.id} tag={tag} size="sm" />
          ))}
          {overflow > 0 && (
            <span className="text-xs text-muted-foreground bg-muted rounded-full px-2 py-0.5 tabular-nums">
              +{overflow}
            </span>
          )}
        </div>
      </td>

      {/* Last visit */}
      <td className={cn('py-3 pr-4 w-28 text-sm tabular-nums', isInactive && 'text-destructive')}>
        {lastVisit}
      </td>

      {/* Total spent */}
      <td className="py-3 pr-4 w-24 text-sm font-medium tabular-nums text-right">
        {formatCurrency(client.total_spent_cents)}
      </td>

      {/* Sessions */}
      <td className="py-3 pr-4 w-16 text-sm tabular-nums text-center">
        {client.total_sessions}
      </td>

      {/* Source */}
      <td className="py-3 pr-4 w-24 text-xs text-muted-foreground hidden lg:table-cell">
        {formatSource(client.source)}
      </td>

      {/* Contact method */}
      <td className="py-3 pr-4 w-16" onClick={(e) => e.stopPropagation()}>
        <ContactIcon
          method={client.preferred_contact ?? 'email'}
          value={client.email ?? client.phone ?? undefined}
        />
      </td>

      {/* Actions */}
      <td className="py-3 pr-4 w-12" onClick={(e) => e.stopPropagation()}>
        <DropdownMenu>
          <DropdownMenuTrigger render={
            <Button variant="ghost" size="icon" className="h-7 w-7">
              <MoreHorizontal className="h-3.5 w-3.5" />
              <span className="sr-only">More actions</span>
            </Button>
          } />
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={(e) => { e.stopPropagation(); router.push(`/clients/${client.id}`) }}>
              <Eye className="mr-2 h-3.5 w-3.5" />
              View profile
            </DropdownMenuItem>
            <DropdownMenuItem onClick={(e) => { e.stopPropagation(); onEdit(client) }}>
              <PencilLine className="mr-2 h-3.5 w-3.5" />
              Edit
            </DropdownMenuItem>
            <DropdownMenuItem onClick={(e) => { e.stopPropagation(); onAddNote(client.id) }}>
              <StickyNote className="mr-2 h-3.5 w-3.5" />
              Add note
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              className="text-destructive focus:text-destructive"
              onClick={handleArchive}
              disabled={isArchiving}
            >
              {isArchiving ? <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" /> : <Archive className="mr-2 h-3.5 w-3.5" />}
              Archive
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </td>
    </tr>
  )
}

function formatSource(source: string | null): string {
  switch (source) {
    case 'public_booking': return 'Booking page'
    case 'walk_in': return 'Walk-in'
    case 'manual': return 'Manual'
    case 'referral': return 'Referral'
    case 'social_media': return 'Social'
    default: return source ?? '—'
  }
}

interface ClientsTableProps {
  clients: Client[]
  tagLibrary: ClientTag[]
  loading?: boolean
  selectedIds: string[]
  onSelectionChange: (ids: string[]) => void
  onEdit: (client: Client) => void
  onAddNote: (clientId: string) => void
}

export function ClientsTable({
  clients,
  tagLibrary,
  loading,
  selectedIds,
  onSelectionChange,
  onEdit,
  onAddNote,
}: ClientsTableProps) {
  const allSelected = clients.length > 0 && clients.every((c) => selectedIds.includes(c.id))
  const someSelected = selectedIds.length > 0 && !allSelected

  function handleSelectAll(checked: boolean) {
    onSelectionChange(checked ? clients.map((c) => c.id) : [])
  }

  function handleSelectOne(id: string, checked: boolean) {
    onSelectionChange(
      checked ? [...selectedIds, id] : selectedIds.filter((sid) => sid !== id)
    )
  }

  if (loading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 8 }).map((_, i) => (
          <Skeleton key={i} className="h-12 w-full rounded-md" />
        ))}
      </div>
    )
  }

  if (clients.length === 0) {
    return null // Parent renders empty state
  }

  return (
    <div className="rounded-lg border border-border/40 overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead>
            <tr className="border-b border-border/40 bg-muted/30">
              <th className="w-10 pl-4 py-3">
                <Checkbox
                  checked={allSelected}
                  ref={(el) => { if (el) (el as HTMLInputElement).indeterminate = someSelected }}
                  onCheckedChange={(v) => handleSelectAll(Boolean(v))}
                  aria-label="Select all clients"
                />
              </th>
              <th className="text-left py-3 pr-4 text-xs font-semibold text-muted-foreground">Client</th>
              <th className="text-left py-3 pr-4 text-xs font-semibold text-muted-foreground w-44">Tags</th>
              <th className="text-left py-3 pr-4 text-xs font-semibold text-muted-foreground w-28">Last visit</th>
              <th className="text-right py-3 pr-4 text-xs font-semibold text-muted-foreground w-24">Spent</th>
              <th className="text-center py-3 pr-4 text-xs font-semibold text-muted-foreground w-16">Sessions</th>
              <th className="text-left py-3 pr-4 text-xs font-semibold text-muted-foreground w-24 hidden lg:table-cell">Source</th>
              <th className="text-left py-3 pr-4 text-xs font-semibold text-muted-foreground w-16">Contact</th>
              <th className="w-12" aria-label="Actions" />
            </tr>
          </thead>
          <tbody>
            {clients.map((client) => (
              <ClientRow
                key={client.id}
                client={client}
                tagLibrary={tagLibrary}
                isSelected={selectedIds.includes(client.id)}
                onSelect={handleSelectOne}
                onEdit={onEdit}
                onAddNote={onAddNote}
              />
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { toast } from 'sonner'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { TagChip, type ClientTag, type TagColor } from '@/components/clients/TagChip'
import { cn } from '@/lib/utils'

const COLORS: { value: TagColor; label: string }[] = [
  { value: 'purple', label: 'Purple' },
  { value: 'blue', label: 'Blue' },
  { value: 'emerald', label: 'Emerald' },
  { value: 'amber', label: 'Amber' },
  { value: 'red', label: 'Red' },
  { value: 'pink', label: 'Pink' },
  { value: 'cyan', label: 'Cyan' },
  { value: 'gray', label: 'Gray' },
]

interface TagFormDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  tag?: ClientTag | null
  onSuccess: (tag: ClientTag) => void
}

export function TagFormDialog({ open, onOpenChange, tag, onSuccess }: TagFormDialogProps) {
  const isEditing = Boolean(tag)
  const [name, setName] = useState(tag?.name ?? '')
  const [color, setColor] = useState<TagColor>(tag?.color ?? 'blue')
  const [icon, setIcon] = useState(tag?.icon ?? '')
  const [description, setDescription] = useState('')
  const [saving, setSaving] = useState(false)
  const [errors, setErrors] = useState<{ name?: string }>({})

  useEffect(() => {
    if (open) {
      setName(tag?.name ?? '')
      setColor(tag?.color ?? 'blue')
      setIcon(tag?.icon ?? '')
      setDescription('')
      setErrors({})
    }
  }, [open, tag])

  async function handleSave() {
    if (!name.trim()) {
      setErrors({ name: 'Tag name is required' })
      return
    }
    setSaving(true)

    try {
      const res = await fetch(
        isEditing ? `/api/client-tags/${tag!.id}` : '/api/client-tags',
        {
          method: isEditing ? 'PATCH' : 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            name: name.trim(),
            color,
            icon: icon.trim() || null,
            description: description.trim() || null,
          }),
        }
      )

      if (!res.ok) {
        const json = await res.json() as { error?: string }
        if (res.status === 409) {
          setErrors({ name: 'A tag with this name already exists' })
          return
        }
        throw new Error(json.error ?? 'Failed to save tag')
      }

      const json = await res.json() as { data: ClientTag }
      toast.success(isEditing ? 'Tag updated' : 'Tag created')
      onOpenChange(false)
      onSuccess(json.data)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to save tag'
      toast.error(message)
    } finally {
      setSaving(false)
    }
  }

  // Live preview tag
  const previewTag: ClientTag = { id: 'preview', name: name || 'Preview', color, icon: icon || null }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[420px]">
        <DialogHeader>
          <DialogTitle>{isEditing ? 'Edit tag' : 'New tag'}</DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Preview */}
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground">Preview:</span>
            <TagChip tag={previewTag} size="sm" />
          </div>

          {/* Name */}
          <div className="space-y-1.5">
            <Label htmlFor="tag-name">
              Name <span className="text-destructive">*</span>
            </Label>
            <Input
              id="tag-name"
              value={name}
              onChange={(e) => { setName(e.target.value); setErrors({}) }}
              placeholder="e.g., VIP, Blackwork, New client"
              aria-invalid={Boolean(errors.name)}
              aria-describedby={errors.name ? 'tag-name-error' : undefined}
            />
            {errors.name && (
              <p id="tag-name-error" role="alert" className="text-xs text-destructive">{errors.name}</p>
            )}
          </div>

          {/* Color */}
          <div className="space-y-1.5">
            <Label>Color</Label>
            <div className="flex flex-wrap gap-2">
              {COLORS.map((c) => (
                <button
                  key={c.value}
                  type="button"
                  className={cn(
                    `tag-chip-${c.value}`,
                    'px-2.5 py-0.5 rounded-full border text-xs font-medium transition-all',
                    color === c.value ? 'ring-2 ring-offset-1 ring-ring' : 'opacity-60 hover:opacity-100'
                  )}
                  onClick={() => setColor(c.value)}
                  aria-pressed={color === c.value}
                >
                  {c.label}
                </button>
              ))}
            </div>
          </div>

          {/* Icon (optional — lucide name) */}
          <div className="space-y-1.5">
            <Label htmlFor="tag-icon">
              Icon{' '}
              <span className="text-xs text-muted-foreground">(optional, Lucide icon name)</span>
            </Label>
            <Input
              id="tag-icon"
              value={icon}
              onChange={(e) => setIcon(e.target.value)}
              placeholder="e.g., star, heart, crown"
            />
          </div>

          {/* Description */}
          <div className="space-y-1.5">
            <Label htmlFor="tag-description">
              Description <span className="text-xs text-muted-foreground">(optional)</span>
            </Label>
            <Textarea
              id="tag-description"
              rows={2}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Internal note about this tag…"
              className="resize-none"
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={saving}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={saving}>
            {saving ? 'Saving…' : isEditing ? 'Save changes' : 'Create tag'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

