  onEdit: (tag: ClientTag) => void
  onDelete: (id: string) => void
}

function SortableTagRow({ tag, onEdit, onDelete }: SortableTagRowProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
