}

interface TagsManagerProps {
  initialTags: (ClientTag & { usage_count?: number })[]
}

export function TagsManager({ initialTags }: TagsManagerProps) {
  const [tags, setTags] = useState<(ClientTag & { usage_count?: number })[]>(initialTags)
  const [formOpen, setFormOpen] = useState(false)
  const [editingTag, setEditingTag] = useState<ClientTag | null>(null)
  const [deleteId, setDeleteId] = useState<string | null>(null)
  const [isDeleting, setIsDeleting] = useState(false)

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  )

  const refetch = useCallback(async () => {
    const res = await fetch('/api/client-tags')
    if (res.ok) {
      const json = await res.json() as { data: (ClientTag & { usage_count?: number })[] }
      setTags(json.data ?? [])
    }
  }, [])

  async function handleDragEnd(event: DragEndEvent) {
    const { active, over } = event
    if (!over || active.id === over.id) return

    const oldIndex = tags.findIndex((t) => t.id === active.id)
    const newIndex = tags.findIndex((t) => t.id === over.id)
    const reordered = arrayMove(tags, oldIndex, newIndex)
    setTags(reordered) // optimistic

    try {
      await fetch('/api/client-tags/reorder', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ordered_ids: reordered.map((t) => t.id) }),
      })
    } catch {
      toast.error('Failed to save order')
      await refetch()
    }
  }

  async function handleDelete() {
    if (!deleteId) return
    setIsDeleting(true)
    try {
      const res = await fetch(`/api/client-tags/${deleteId}`, { method: 'DELETE' })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to delete tag')
      }
      toast.success('Tag deleted')
      setTags((prev) => prev.filter((t) => t.id !== deleteId))
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to delete tag'
      toast.error(message)
    } finally {
      setIsDeleting(false)
      setDeleteId(null)
    }
  }

  function handleEdit(tag: ClientTag) {
    setEditingTag(tag)
    setFormOpen(true)
  }

  function handleFormSuccess(tag: ClientTag) {
    setTags((prev) => {
      const idx = prev.findIndex((t) => t.id === tag.id)
      if (idx >= 0) {
        const next = [...prev]
        next[idx] = { ...next[idx], ...tag }
        return next
      }
      return [...prev, tag]
    })
    setEditingTag(null)
  }

  const tagToDelete = tags.find((t) => t.id === deleteId)

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-base font-semibold">Client tags</h2>
          <p className="text-sm text-muted-foreground mt-0.5">
            Create and manage tags to categorize your clients.
          </p>
        </div>
        <Button size="sm" onClick={() => { setEditingTag(null); setFormOpen(true) }}>
          <Plus className="mr-2 h-4 w-4" />
          New tag
        </Button>
      </div>

      {tags.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 gap-4 text-center">
          <div className="rounded-xl bg-muted/50 p-4">
            <Tag className="h-10 w-10 text-muted-foreground/50" />
          </div>
          <div className="space-y-1">
            <h3 className="text-sm font-medium">No tags yet</h3>
            <p className="text-sm text-muted-foreground max-w-xs">
              Create your first tag to start categorizing clients — VIP, new client, blackwork, etc.
            </p>
          </div>
          <Button size="sm" onClick={() => { setEditingTag(null); setFormOpen(true) }}>
            <Plus className="mr-2 h-4 w-4" />
            New tag
          </Button>
        </div>
      ) : (
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragEnd={handleDragEnd}
        >
          <SortableContext items={tags.map((t) => t.id)} strategy={verticalListSortingStrategy}>
            <div className="space-y-2">
              {tags.map((tag) => (
                <SortableTagRow
                  key={tag.id}
                  tag={tag}
                  onEdit={handleEdit}
                  onDelete={setDeleteId}
                />
              ))}
            </div>
          </SortableContext>
        </DndContext>
      )}

      <TagFormDialog
        open={formOpen}
        onOpenChange={(v) => {
          setFormOpen(v)
          if (!v) setEditingTag(null)
        }}
        tag={editingTag}
        onSuccess={handleFormSuccess}
      />

      <AlertDialog open={Boolean(deleteId)} onOpenChange={(v) => { if (!v) setDeleteId(null) }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete &ldquo;{tagToDelete?.name}&rdquo;?</AlertDialogTitle>
            <AlertDialogDescription>
              This will remove the tag from your library. Clients who have this tag will lose it.
              This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              disabled={isDeleting}
            >
              Delete tag
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

