      .select('id, first_name, last_name, email, phone, tags, total_spent_cents, total_sessions, last_visit_at, no_show_count, source, preferred_contact, archived_at, created_at, updated_at, date_of_birth, address, notes, referral_source, cancellation_count, loyalty_points, lifetime_value_cents, avg_session_value_cents, consent_minor')
      .eq('studio_id', auth.studioId)
      .is('archived_at', null)
