'use client'

import { useState, useCallback, useEffect } from 'react'
import { Users, SearchX, Plus, RefreshCw } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { ClientsTable } from '@/components/clients/ClientsTable'
import { ClientFilterBar, type ClientFilters } from '@/components/clients/ClientFilterBar'
import { BulkActionsBar } from '@/components/clients/BulkActionsBar'
import { ClientDrawer } from '@/components/clients/ClientDrawer'
import { AddNoteModal } from '@/components/clients/notes/AddNoteModal'
import type { ClientTag } from '@/components/clients/TagChip'
import type { Database } from '@/lib/supabase/types'

type Client = Database['public']['Tables']['clients']['Row']

interface ClientsPageClientProps {
  initialClients: Client[]
  tagLibrary: ClientTag[]
}

const DEFAULT_FILTERS: ClientFilters = {
  q: '',
  tags: [],
  vip: false,
  inactive: false,
  noShows: false,
  showArchived: false,
  spendingTier: '',
}

export function ClientsPageClient({ initialClients, tagLibrary }: ClientsPageClientProps) {
  const [clients, setClients] = useState<Client[]>(initialClients)
  const [filters, setFilters] = useState<ClientFilters>(DEFAULT_FILTERS)
  const [selectedIds, setSelectedIds] = useState<string[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [editingClient, setEditingClient] = useState<Client | null>(null)
  const [noteClientId, setNoteClientId] = useState<string | null>(null)
  const [page, setPage] = useState(1)
  const [hasMore, setHasMore] = useState(false)

  const fetchClients = useCallback(async (f: ClientFilters, p = 1) => {
    setLoading(true)
    setError(null)
    try {
      const params = new URLSearchParams()
      if (f.q) params.set('q', f.q)
      if (f.tags.length) params.set('tags', f.tags.join(','))
      if (f.vip) params.set('vip', 'true')
      if (f.inactive) params.set('inactive', 'true')
      if (f.noShows) params.set('no_show', 'true')
      if (!f.showArchived) params.set('archived', 'false')
      else params.set('archived', 'any')
      if (f.spendingTier) params.set('spending', f.spendingTier)
      params.set('page', String(p))
      params.set('per_page', '50')

      const res = await fetch(`/api/clients?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to load clients')
      const json = await res.json() as { data: Client[]; count: number }

      if (p === 1) {
        setClients(json.data ?? [])
      } else {
        setClients((prev) => [...prev, ...(json.data ?? [])])
      }
      setHasMore((json.data?.length ?? 0) >= 50)
    } catch {
      setError('Failed to load clients. Please try again.')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    void fetchClients(filters, 1)
    setPage(1)
    setSelectedIds([])
  }, [filters, fetchClients])

  function handleFiltersChange(f: ClientFilters) {
    setFilters(f)
  }

  function handleLoadMore() {
    const nextPage = page + 1
    setPage(nextPage)
    void fetchClients(filters, nextPage)
  }

  function handleEditClient(client: Client) {
    setEditingClient(client)
    setDrawerOpen(true)
  }

  function handleNewClient() {
    setEditingClient(null)
    setDrawerOpen(true)
  }

  function handleDrawerSuccess(client: Client) {
    setClients((prev) => {
      const idx = prev.findIndex((c) => c.id === client.id)
      if (idx >= 0) {
        const next = [...prev]
        next[idx] = client
        return next
      }
      return [client, ...prev]
    })
  }

  function handleRefresh() {
    void fetchClients(filters, 1)
    setPage(1)
  }

  const hasActiveFilters = filters.q || filters.tags.length > 0 || filters.vip ||
    filters.inactive || filters.noShows || filters.spendingTier

  return (
    <div className="flex flex-col gap-4 p-4 lg:p-6">
      {/* Page header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">Clients</h1>
          <p className="text-sm text-muted-foreground mt-0.5">
            {clients.length > 0 && (
              <span className="tabular-nums">{clients.length} client{clients.length !== 1 ? 's' : ''}</span>
            )}
          </p>
        </div>
        <Button onClick={handleNewClient}>
          <Plus className="mr-2 h-4 w-4" />
          New client
        </Button>
      </div>

      {/* Filter bar */}
      <ClientFilterBar
        filters={filters}
        onChange={handleFiltersChange}
        tagLibrary={tagLibrary}
      />

      {/* Bulk actions */}
      {selectedIds.length > 0 && (
        <BulkActionsBar
          selectedIds={selectedIds}
          tagLibrary={tagLibrary}
          onClearSelection={() => setSelectedIds([])}
          onArchived={() => void fetchClients(filters, 1)}
          onTagsApplied={() => void fetchClients(filters, 1)}
        />
      )}

      {/* Error state */}
      {error && (
        <Alert variant="destructive">
          <AlertDescription className="flex items-center gap-2">
            {error}
            <Button variant="outline" size="sm" onClick={handleRefresh} className="ml-auto gap-1.5">
              <RefreshCw className="h-3.5 w-3.5" />
              Try again
            </Button>
          </AlertDescription>
        </Alert>
      )}

      {/* Empty states */}
      {!loading && !error && clients.length === 0 && (
        hasActiveFilters ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4 text-center">
            <SearchX className="h-10 w-10 text-muted-foreground/50" />
            <div className="space-y-1">
              <h3 className="text-base font-medium">No clients match these filters</h3>
              <p className="text-sm text-muted-foreground max-w-sm">
                Try different tags, spending range, or clear all filters to see everyone.
              </p>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setFilters(DEFAULT_FILTERS)}
            >
              Clear filters
            </Button>
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center py-20 gap-4 text-center">
            <div className="rounded-xl bg-muted/50 p-4">
              <Users className="h-12 w-12 text-muted-foreground/50" />
            </div>
            <div className="space-y-1">
              <h3 className="text-base font-medium">Your first client will appear here</h3>
              <p className="text-sm text-muted-foreground max-w-sm">
                when they book — or add one manually.
              </p>
            </div>
            <Button onClick={handleNewClient}>
              <Plus className="mr-2 h-4 w-4" />
              Add your first client
            </Button>
          </div>
        )
      )}

      {/* Table */}
      {(loading || clients.length > 0) && (
        <ClientsTable
          clients={clients}
          tagLibrary={tagLibrary}
          loading={loading && clients.length === 0}
          selectedIds={selectedIds}
          onSelectionChange={setSelectedIds}
          onEdit={handleEditClient}
          onAddNote={(id) => setNoteClientId(id)}
        />
      )}

      {/* Load more */}
      {hasMore && !loading && (
        <div className="flex justify-center">
          <Button variant="outline" onClick={handleLoadMore}>
            Load more
          </Button>
        </div>
      )}

      {/* Client drawer */}
      <ClientDrawer
        open={drawerOpen}
        onOpenChange={(v) => {
          setDrawerOpen(v)
          if (!v) setEditingClient(null)
        }}
        client={editingClient}
        tagLibrary={tagLibrary}
        onSuccess={handleDrawerSuccess}
      />

      {/* Quick add note */}
      {noteClientId && (
        <AddNoteModal
          open={Boolean(noteClientId)}
          onOpenChange={(v) => { if (!v) setNoteClientId(null) }}
          clientId={noteClientId}
        />
      )}
    </div>
  )
}

