import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { TagsManager } from '@/components/settings/tags/TagsManager'
import type { ClientTag } from '@/components/clients/TagChip'

export const metadata: Metadata = { title: 'Client Tags' }

export default async function Page() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // Fetch tags with usage_count via a LEFT JOIN count
  // Since usage_count isn't a column, we compute it via a separate count query
  const tagsResult = await supabase
    .from('client_tags')
    .select('id, name, color, icon, description, created_at, updated_at')
    .eq('studio_id', auth.studioId)
    .order('name')

  const tags = tagsResult.data ?? []

  // For each tag, count how many clients have it in their tags array
  // This is done in bulk via a single RPC or via individual counts.
  // We do a simple approach: fetch client.tags arrays, count occurrences client-side
  const { data: clientTagData } = await supabase
    .from('clients')
    .select('tags')
    .eq('studio_id', auth.studioId)
    .is('archived_at', null)

  const usageCounts: Record<string, number> = {}
  for (const client of clientTagData ?? []) {
    for (const tagRef of client.tags ?? []) {
      usageCounts[tagRef] = (usageCounts[tagRef] ?? 0) + 1
    }
  }

  const tagsWithCount: (ClientTag & { usage_count?: number })[] = tags.map((tag) => ({
    id: tag.id,
    name: tag.name,
    color: tag.color as ClientTag['color'],
    icon: tag.icon,
    description: tag.description,
    usage_count: usageCounts[tag.id] ?? usageCounts[tag.name] ?? 0,
  }))

  return (
    <div className="p-4 lg:p-6">
      <TagsManager initialTags={tagsWithCount} />
    </div>
  )
}

