'use client'

import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type PhotoKind = Database['public']['Tables']['booking_photos']['Row']['kind']

const KINDS: { value: PhotoKind; label: string }[] = [
  { value: 'reference', label: 'Reference' },
  { value: 'before', label: 'Before' },
  { value: 'during', label: 'During' },
  { value: 'after', label: 'After' },
  { value: 'healed', label: 'Healed' },
]

interface KindFilterToggleProps {
  value: PhotoKind | 'all'
  onChange: (value: PhotoKind | 'all') => void
  counts?: Partial<Record<PhotoKind, number>>
}

export function KindFilterToggle({ value, onChange, counts }: KindFilterToggleProps) {
  const totalCount = counts ? Object.values(counts).reduce((a, b) => a + b, 0) : undefined

  return (
    <div className="flex flex-wrap gap-1">
      <Button
        variant={value === 'all' ? 'default' : 'outline'}
        size="sm"
        className="h-7 px-3 text-xs"
        onClick={() => onChange('all')}
      >
        All
        {totalCount !== undefined && totalCount > 0 && (
          <span className={cn('ml-1.5 tabular-nums text-[10px]', value === 'all' ? 'text-primary-foreground/70' : 'text-muted-foreground')}>
            {totalCount}
          </span>
        )}
      </Button>
      {KINDS.map((k) => {
        const count = counts?.[k.value]
        return (
          <Button
            key={k.value}
            variant={value === k.value ? 'default' : 'outline'}
            size="sm"
            className="h-7 px-3 text-xs"
            onClick={() => onChange(k.value)}
          >
            {k.label}
            {count !== undefined && count > 0 && (
              <span className={cn('ml-1.5 tabular-nums text-[10px]', value === k.value ? 'text-primary-foreground/70' : 'text-muted-foreground')}>
                {count}
              </span>
            )}
          </Button>
        )
      })}
    </div>
  )
}

