import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const ReorderSchema = z.object({
  ordered_ids: z.array(z.string().uuid()).min(1),
})

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = ReorderSchema.safeParse(body)
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  try {
    const supabase = await createClient()

    // Verify all tags belong to this studio before updating
    const { data: existingTags, error: fetchError } = await supabase
      .from('client_tags')
      .select('id')
      .in('id', parsed.data.ordered_ids)
      .eq('studio_id', authUser.studioId)

    if (fetchError) throw fetchError

    if (existingTags.length !== parsed.data.ordered_ids.length) {
      return NextResponse.json({ error: 'One or more tags not found' }, { status: 404 })
    }

    // Update sort_order for each tag — sort_order exists in DB via Sprint 3 migration
    // The generated types may not include it in Update type, use raw approach
    const updates = parsed.data.ordered_ids.map((id, index) => {
      const payload: Record<string, string | number> = {
        updated_at: new Date().toISOString(),
        sort_order: index,
      }
      return supabase
        .from('client_tags')
        .update(payload as Parameters<ReturnType<typeof supabase.from>['update']>[0])
        .eq('id', id)
        .eq('studio_id', authUser.studioId)
    })

    await Promise.all(updates)

    return NextResponse.json({ success: true })
  } catch (err) {
    logger.error({ err }, 'tag reorder unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

