// Update sort_order for each tag.
// sort_order column exists in DB (added in Sprint 3 migration) but may not be reflected
// in the generated Update type yet. We build the payload as a const-asserted object
// and supply only the fields we know are in the Update type, adding sort_order via
// Object.assign to avoid the exactOptionalPropertyTypes constraint.
const updates = parsed.data.ordered_ids.map((id, index) => {
  const base: { updated_at: string } = { updated_at: new Date().toISOString() }
  const payload = Object.assign(base, { sort_order: index }) as { updated_at: string }
  return supabase
    .from('client_tags')
    .update(payload)
    .eq('id', id)
    .eq('studio_id', authUser.studioId)
})

await Promise.all(updates)

